	],
};

export const Square = Template.bind({});
Square.args = {
	squareButtons: true,
	options: [
		{
			label: 'A',
			value: 'a',
		},
		{
			label: 'B',
			value: 'b',
		},
		{
			label: 'C',
			value: 'c',
		},
	],
};

const iconOptions: Array<SegmentOption<string> & { icon: IconName }> = [
