     7	import SegmentControlItem from './SegmentControlItem.vue';
     8	
     9	defineOptions({ inheritAttrs: false });
    10	
    11	const props = withDefaults(defineProps<SegmentControlProps<Value>>(), {
    12		disabled: false,
    13		size: 'default',
    14		squareButtons: false,
    15		loop: true,
    16	});
    17	
    18	const emit = defineEmits<{
    19		'update:modelValue': [value: Value, e: MouseEvent];
    20	}>();
    21	
    22	defineSlots<{ option?: (props: SegmentOption<Value>) => unknown }>();
    23	
    24	const attrs = useAttrs();
    25	const rootClass = computed(() => attrs.class);
    26	const rootAttrs = computed(() => reactiveOmit(attrs, 'class'));
    27	
    28	/** Last pointer event, so consumers can read ctrl/meta (e.g. open-in-new-tab). */
    29	const lastPointerEvent = ref<MouseEvent>();
    30	
    31	/**
    32	 * reka-ui selects on arrow keys via a window keydown listener. That is blocked
    33	 * when keydown doesn't reach window — e.g. our stopPropagation below (so canvas
    34	 * node-nav / editor shortcuts don't also fire), or an ancestor @keydown.stop
    35	 * (modals, keybinding wrappers). RovingFocus still moves focus; we click the
    36	 * focused radio after nextTick to complete selection.
    37	 */
    38	const ARROW_KEYS = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'];
    39	
    40	function optionKey(value: Value): string {
    41		return `${typeof value}:${String(value)}`;
    42	}
    43	
    44	function toRadioValue(value: Value | undefined): string | undefined {
    45		if (value === undefined || !props.options?.some((option) => option.value === value)) {
    46			return undefined;
    47		}
    48		return optionKey(value);
    49	}
    50	
    51	function findOptionByRadioValue(raw: AcceptableValue): SegmentOption<Value> | undefined {
    52		if (typeof raw !== 'string') {
    53			return undefined;
    54		}
    55		return props.options?.find((option) => optionKey(option.value) === raw);
    56	}
    57	
    58	function onKeyDown(event: KeyboardEvent) {
    59		if (!ARROW_KEYS.includes(event.key)) return;
    60	
    61		// Keep arrow keys inside the control so canvas/editor shortcuts don't also fire
    62		event.stopPropagation();
    63		if (props.disabled) return;
    64	
    65		const group = event.currentTarget;
    66		if (!(group instanceof HTMLElement)) return;
    67	
    68		// RovingFocus moves focus in nextTick; wait for that before selecting
    69		void nextTick(() => {
    70			const active = document.activeElement;
    71			if (!(active instanceof HTMLElement) || !group.contains(active)) {
    72				return;
    73			}
    74			if (active.getAttribute('role') !== 'radio') {
    75				return;
    76			}
    77			if (active.getAttribute('data-state') === 'checked') {
    78				return;
    79			}
    80			active.click();
    81		});
    82	}
    83	
    84	function onItemClickCapture(event: MouseEvent) {
    85		const target = event.target;
    86		if (!(target instanceof HTMLElement)) return;
    87		if (target.closest('[role="radio"]')) {
    88			lastPointerEvent.value = event;
    89		}
    90	}
    91	
    92	function onUpdate(raw: AcceptableValue) {
    93		const option = findOptionByRadioValue(raw);
    94		if (!option || props.disabled || option.disabled) {
    95			return;
    96		}
    97	
    98		const event = lastPointerEvent.value ?? new MouseEvent('click');
    99		lastPointerEvent.value = undefined;
   100		emit('update:modelValue', option.value, event);
   101	}
   102	</script>
