+		</n8n-segment-control>`,
+	methods,
+	data() {
+		return {
+			val: 'test',
+		};
+	},
+});
+
+export const Default = Template.bind({});
+Default.args = {
+	options: defaultOptions,
+};
+
+export const Sizes: StoryFn = () => ({
+	components: { N8nSegmentControl },
+	setup() {
+		const values = ref<Record<SegmentControlSize, string>>({
+			mini: 'test',
+			small: 'test',
+			default: 'test',
+			large: 'test',
